        var a=attack("xy1_en_080",0);var m=game(a);var tool=hand(m,B,"tool");m.attachToolByEffect(A,B,EffectSourceZone.HAND,tool.instanceId(),B,active(m,B));var own=hand(m,A,"tool");m.attachToolByEffect(A,A,EffectSourceZone.HAND,own.instanceId(),A,active(m,A));m.attack(A,a.id());check(m.activePokemonView(B).damage()==0,"Tool discarded after damage");var p=m.effectCardPrompt(A);check(p.candidates().equals(List.of(tool)),"Tool discard admitted own attachments");cards(m,List.of(tool.instanceId()));check(m.activePokemonView(B).damage()==30&&m.privateView(B).discard().contains(tool)&&m.activePokemonView(A).attachedTools().contains(own),"Tool discard owner/damage order");
